using UnityEditor;
using UnityEngine;

/// <summary>
/// Editor tool that marks the selected prefab assets, and all of their children,
/// as static, and ensures "Static Shadow Caster" is enabled on any object
/// carrying a MeshRenderer.
/// </summary>
public static class MakeStaticAllSelectedPrefabs
{
    [MenuItem("Assets/Optimizations/Make static all selected prefabs", true)]
    private static bool ValidateMakeStatic()
    {
        foreach (var obj in Selection.gameObjects)
        {
            if (PrefabUtility.GetPrefabAssetType(obj) != PrefabAssetType.NotAPrefab)
                return true;
        }
        return false;
    }

    [MenuItem("Assets/Optimizations/Make static all selected prefabs")]
    private static void MakeStatic()
    {
        GameObject[] selectedPrefabs = Selection.gameObjects;
        int modifiedPrefabCount = 0;
        int modifiedObjectCount = 0;
        int modifiedShadowCasterCount = 0;

        // Suspends automatic reimporting while we modify prefabs, so dependent assets
        // (nested prefabs, prefab variants) get reimported once in a batch at
        // StopAssetEditing() instead of after every single SaveAsPrefabAsset call.
        AssetDatabase.StartAssetEditing();

        try
        {
            for (int i = 0; i < selectedPrefabs.Length; i++)
            {
                GameObject selected = selectedPrefabs[i];

                if (PrefabUtility.GetPrefabAssetType(selected) == PrefabAssetType.NotAPrefab)
                    continue;

                string assetPath = AssetDatabase.GetAssetPath(selected);
                if (string.IsNullOrEmpty(assetPath))
                    continue;

                EditorUtility.DisplayProgressBar(
                    "Making prefabs static",
                    $"Processing {assetPath}",
                    (float)i / selectedPrefabs.Length);

                GameObject prefabRoot = PrefabUtility.LoadPrefabContents(assetPath);
                bool prefabChanged = false;

                try
                {
                    Transform[] allTransforms = prefabRoot.GetComponentsInChildren<Transform>(true);
                    foreach (Transform t in allTransforms)
                    {
                        GameObject go = t.gameObject;

                        if (!go.isStatic)
                        {
                            go.isStatic = true;
                            modifiedObjectCount++;
                            prefabChanged = true;
                        }

                        if (go.TryGetComponent<MeshRenderer>(out MeshRenderer renderer))
                        {
                            if (!renderer.staticShadowCaster)
                            {
                                renderer.staticShadowCaster = true;
                                modifiedShadowCasterCount++;
                                prefabChanged = true;
                            }
                        }
                    }

                    if (prefabChanged)
                    {
                        PrefabUtility.SaveAsPrefabAsset(prefabRoot, assetPath);
                        modifiedPrefabCount++;
                    }
                }
                finally
                {
                    PrefabUtility.UnloadPrefabContents(prefabRoot);
                }
            }
        }
        finally
        {
            AssetDatabase.StopAssetEditing();
            EditorUtility.ClearProgressBar();
        }

        AssetDatabase.SaveAssets();

        Debug.Log($"Make static: modified {modifiedObjectCount} GameObject(s), " +
                  $"enabled Static Shadow Caster on {modifiedShadowCasterCount} renderer(s), " +
                  $"across {modifiedPrefabCount} prefab(s).");
    }
}
